// src/pages/DashboardProf.jsx
import React, { useState, useEffect } from "react";
import { useNavigate } from "react-router-dom";

const DashboardProf = () => {
  const navigate = useNavigate();
  const [user, setUser] = useState(null);
  const [stats, setStats] = useState(null);
  const [loading, setLoading] = useState(true);

  useEffect(() => {
    const fetchUserData = async () => {
      const userData = localStorage.getItem("user");
      if (!userData) {
        navigate("/login");
        return;
      }

      const userObj = JSON.parse(userData);
      if (userObj.role !== "teacher") {
        alert("❌ Accès réservé aux professeurs");
        navigate("/login");
        return;
      }

      setUser(userObj);
      await fetchTeacherStats(userObj.id);
    };

    fetchUserData();
  }, [navigate]);

  const fetchTeacherStats = async (teacherId) => {
    try {
      setLoading(true);
      const token = localStorage.getItem("token");
      
      // À remplacer par votre véritable endpoint API
      const response = await fetch(`/api/teachers/${teacherId}/stats`, {
        method: 'GET',
        headers: {
          'Authorization': `Bearer ${token}`,
          'Content-Type': 'application/json',
        },
      });

      if (response.ok) {
        const data = await response.json();
        setStats(data);
      } else {
        console.error("Erreur lors de la récupération des statistiques");
        setStats({
          coursesCount: 0,
          studentsCount: 0,
          pendingAssignments: 0,
          successRate: 0
        });
      }
    } catch (error) {
      console.error("Erreur:", error);
      setStats({
        coursesCount: 0,
        studentsCount: 0,
        pendingAssignments: 0,
        successRate: 0
      });
    } finally {
      setLoading(false);
    }
  };

  const handleLogout = () => {
    localStorage.removeItem("user");
    localStorage.removeItem("token");
    navigate("/login");
  };

  const handleMenuClick = (menuItem) => {
    switch(menuItem) {
      case "Voir mes cours":
        navigate("/mes-cours");
        break;
      case "Voir les étudiants":
        navigate("/etudiants");
        break;
      case "Gérer les notes":
        navigate("/notes");
        break;
      case "Voir les rapports":
        navigate("/rapports");
        break;
      default:
        break;
    }
  };

  const menuItems = [
    { label: "Voir mes cours", icon: "📚", color: "#3B82F6" },
    { label: "Voir les étudiants", icon: "👨‍🎓", color: "#10B981" },
    { label: "Gérer les notes", icon: "📊", color: "#F59E0B" },
    { label: "Voir les rapports", icon: "📋", color: "#8B5CF6" }
  ];

  if (!user) {
    return <p>Chargement du tableau de bord...</p>;
  }

  return (
    <div style={{ padding: "20px", fontFamily: "Arial, sans-serif", maxWidth: "1200px", margin: "0 auto" }}>
      {/* Header */}
      <header style={{ 
        display: "flex", 
        justifyContent: "space-between", 
        alignItems: "center",
        marginBottom: "30px",
        paddingBottom: "20px",
        borderBottom: "1px solid #ddd"
      }}>
        <div>
          <h1 style={{ margin: 0, color: "#333" }}>Tableau de Bord Professeur</h1>
          <p style={{ margin: "5px 0 0 0", color: "#666" }}>Gestion académique</p>
        </div>
        <div style={{ display: "flex", alignItems: "center", gap: "15px" }}>
          <div style={{ textAlign: "right" }}>
            <div style={{ fontWeight: "bold" }}>Prof. {user.nom}</div>
            <div style={{ fontSize: "0.9em", color: "#666" }}>{user.role}</div>
          </div>
          <button 
            onClick={handleLogout}
            style={{
              padding: "8px 16px",
              backgroundColor: "#dc3545",
              color: "white",
              border: "none",
              borderRadius: "5px",
              cursor: "pointer"
            }}
          >
            Déconnexion
          </button>
        </div>
      </header>

      {/* Welcome Section */}
      <section style={{ 
        backgroundColor: "#f8f9fa", 
        padding: "20px", 
        borderRadius: "8px",
        marginBottom: "30px"
      }}>
        <div style={{ display: "flex", justifyContent: "space-between", alignItems: "center" }}>
          <div>
            <h2 style={{ margin: "0 0 10px 0", color: "#333" }}>
              Bonjour, Professeur {user.nom} 👨‍🏫
            </h2>
            <p style={{ margin: 0, color: "#666" }}>
              Bienvenue sur votre espace de gestion pédagogique
            </p>
          </div>
          <div style={{ 
            width: "60px", 
            height: "60px", 
            backgroundColor: "#007bff",
            borderRadius: "50%",
            display: "flex",
            alignItems: "center",
            justifyContent: "center",
            fontSize: "24px"
          }}>
            👨‍🏫
          </div>
        </div>
        
        <div style={{ display: "flex", gap: "20px", marginTop: "15px" }}>
          <div>
            <strong>📧 Email:</strong> {user.email}
          </div>
          <div>
            <strong>🎯 Rôle:</strong> {user.role}
          </div>
          <div>
            <strong>🆔 ID:</strong> {user.id}
          </div>
        </div>
      </section>

      {/* Menu Grid */}
      <section style={{ marginBottom: "30px" }}>
        <h3 style={{ color: "#333", marginBottom: "20px" }}>Actions Rapides</h3>
        <div style={{ 
          display: "grid", 
          gridTemplateColumns: "repeat(auto-fit, minmax(200px, 1fr))",
          gap: "15px" 
        }}>
          {menuItems.map((item, index) => (
            <button
              key={index}
              onClick={() => handleMenuClick(item.label)}
              style={{
                padding: "20px",
                backgroundColor: "white",
                border: "1px solid #ddd",
                borderRadius: "8px",
                cursor: "pointer",
                textAlign: "center",
                transition: "all 0.3s ease"
              }}
              onMouseOver={(e) => {
                e.target.style.transform = "translateY(-2px)";
                e.target.style.boxShadow = "0 4px 8px rgba(0,0,0,0.1)";
              }}
              onMouseOut={(e) => {
                e.target.style.transform = "translateY(0)";
                e.target.style.boxShadow = "none";
              }}
            >
              <div style={{ 
                fontSize: "24px", 
                marginBottom: "10px",
                color: item.color
              }}>
                {item.icon}
              </div>
              <div style={{ fontWeight: "bold", color: "#333" }}>
                {item.label}
              </div>
            </button>
          ))}
        </div>
      </section>

      {/* Stats Section */}
      <section>
        <h3 style={{ color: "#333", marginBottom: "20px" }}>Aperçu du Semestre</h3>
        {loading ? (
          <div style={{ textAlign: "center", padding: "40px" }}>
            <p>Chargement des statistiques...</p>
          </div>
        ) : (
          <div style={{ 
            display: "grid", 
            gridTemplateColumns: "repeat(auto-fit, minmax(200px, 1fr))",
            gap: "15px" 
          }}>
            <div style={{ 
              backgroundColor: "white", 
              padding: "20px", 
              borderRadius: "8px",
              border: "1px solid #ddd",
              textAlign: "center"
            }}>
              <div style={{ fontSize: "24px", marginBottom: "10px" }}>📚</div>
              <div style={{ fontSize: "24px", fontWeight: "bold", color: "#333" }}>
                {stats?.coursesCount || 0}
              </div>
              <div style={{ color: "#666" }}>Cours assignés</div>
            </div>
            
            <div style={{ 
              backgroundColor: "white", 
              padding: "20px", 
              borderRadius: "8px",
              border: "1px solid #ddd",
              textAlign: "center"
            }}>
              <div style={{ fontSize: "24px", marginBottom: "10px" }}>👨‍🎓</div>
              <div style={{ fontSize: "24px", fontWeight: "bold", color: "#333" }}>
                {stats?.studentsCount || 0}
              </div>
              <div style={{ color: "#666" }}>Étudiants</div>
            </div>
            
            <div style={{ 
              backgroundColor: "white", 
              padding: "20px", 
              borderRadius: "8px",
              border: "1px solid #ddd",
              textAlign: "center"
            }}>
              <div style={{ fontSize: "24px", marginBottom: "10px" }}>📝</div>
              <div style={{ fontSize: "24px", fontWeight: "bold", color: "#333" }}>
                {stats?.pendingAssignments || 0}
              </div>
              <div style={{ color: "#666" }}>Devoirs en attente</div>
            </div>
            
            <div style={{ 
              backgroundColor: "white", 
              padding: "20px", 
              borderRadius: "8px",
              border: "1px solid #ddd",
              textAlign: "center"
            }}>
              <div style={{ fontSize: "24px", marginBottom: "10px" }}>✅</div>
              <div style={{ fontSize: "24px", fontWeight: "bold", color: "#333" }}>
                {stats?.successRate || 0}%
              </div>
              <div style={{ color: "#666" }}>Taux de réussite</div>
            </div>
          </div>
        )}
      </section>
    </div>
  );
};

export default DashboardProf;
